s=open(p).read()
a=s.index("    /// Adds a message at the end of the queue and returns its sequence")
b=s.index("    /// Removes and returns the message with this arrival index.")
new='''    /// Adds a message of a standard queue at the end of the queue.
    pub fn push(&mut self, message: Message) {
        debug_assert!(message.fifo.is_none(), "standard queues keep no groups");
        self.insert(message);
    }

    /// Adds a message of a FIFO queue at the end of the queue and returns the
    /// sequence number it takes.
    pub fn push_fifo(&mut self, mut message: Message, group_id: String) -> u64 {
        let sequence_number = self.next_sequence;
        self.next_sequence += 1;
        message.fifo = Some(FifoPlace {
            group_id,
            sequence_number,
        });
        self.insert(message);
        sequence_number
    }

    fn insert(&mut self, message: Message) {
        self.oldest_sent_at = Some(
            self.oldest_sent_at
                .map_or(message.sent_at, |t| t.min(message.sent_at)),
        );
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    /// Adds a message moved here from another queue's dead-letter handling.
    pub fn push_dead_letter(&mut self, mut message: Message, now: u64) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.delayed_until = 0;
        message.invisible_until = 0;
        message.handle = None;
        match message.fifo.take() {
            Some(place) => {
                self.push_fifo(message, place.group_id);
            }
            None => self.push(message),
        }
        self.expire(now);
    }

